     "solution": "from bisect import bisect_left, bisect_right\nn = int(input())\na = sorted(map(int, input().split()))\nq = int(input())\nout = []\nfor _ in range(q):\n    l, r = map(int, input().split())\n    out.append(bisect_right(a, r) - bisect_left(a, l))\nprint(\"\\n\".join(map(str, out)))\n",
